// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./SupplyChain.sol";

/**
 * @title AlertSystem
 * @dev Simplified alert system that works with the hybrid SupplyChain
 */
contract AlertSystem {
    SupplyChain public supplyChain;

    enum AlertType {
        TemperatureViolation,
        ExpiryWarning,
        UnauthorizedAccess,
        QualityIssue,
        DelayAlert
    }

    struct Alert {
        uint256 id;
        AlertType alertType;
        uint256 productId;
        string message;
        address triggeredBy;
        uint256 timestamp;
        bool resolved;
    }

    mapping(uint256 => Alert) public alerts;
    uint256 public alertCount;

    event AlertTriggered(uint256 indexed alertId, AlertType indexed alertType, uint256 indexed productId, string message);
    event AlertResolved(uint256 indexed alertId, address indexed resolvedBy);

    constructor(address _supplyChain) {
        supplyChain = SupplyChain(_supplyChain);
    }

    function triggerAlert(
        AlertType _type,
        uint256 _productId,
        string memory _message
    ) public returns (uint256) {
        alertCount++;
        
        alerts[alertCount] = Alert({
            id: alertCount,
            alertType: _type,
            productId: _productId,
            message: _message,
            triggeredBy: msg.sender,
            timestamp: block.timestamp,
            resolved: false
        });

        emit AlertTriggered(alertCount, _type, _productId, _message);
        return alertCount;
    }

    function resolveAlert(uint256 _alertId) public {
        require(_alertId > 0 && _alertId <= alertCount, "Invalid alert ID");
        require(!alerts[_alertId].resolved, "Alert already resolved");
        
        alerts[_alertId].resolved = true;
        emit AlertResolved(_alertId, msg.sender);
    }

    function getUnresolvedAlerts() public view returns (uint256[] memory) {
        uint256 unresolvedCount = 0;
        
        for (uint256 i = 1; i <= alertCount; i++) {
            if (!alerts[i].resolved) {
                unresolvedCount++;
            }
        }

        uint256[] memory unresolvedIds = new uint256[](unresolvedCount);
        uint256 index = 0;
        
        for (uint256 i = 1; i <= alertCount; i++) {
            if (!alerts[i].resolved) {
                unresolvedIds[index] = i;
                index++;
            }
        }

        return unresolvedIds;
    }
}

