// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./IStructs.sol";

/**
 * @title SupplyChain - Hybrid Advanced Supply Chain
 * @dev Combines simple role-based access with advanced features:
 * - Simple string-based roles (like working version)
 * - Per-user status tracking
 * - Full product lifecycle with environmental data
 * - Financial integration ready
 * - Inventory tracking ready
 */
contract SupplyChain {
    
    // --- STRUCTS ---
    struct Product {
        uint256 id;
        string name;
        string serialNumber;
        string batchNumber;
        IStructs.ProductCategory category;
        IStructs.ProductStatus status;
        address currentOwner;
        address manufacturer;
        uint256 quantity;
        uint256 unitCost;
        uint256 createdAt;
        uint256 expiryDate;
        bool requiresTemperatureControl;
        int256 minTemperature;
        int256 maxTemperature;
        address[] history;
        uint256[] historyTimestamps;
    }

    struct EnvironmentalReading {
        int256 temperature;
        uint256 humidity;
        uint256 timestamp;
        address recordedBy;
    }

    // --- STORAGE ---
    mapping(uint256 => Product) public products;
    uint256 public productCount = 0;

    // Simple role system (like working version)
    mapping(address => string) public roles;
    
    // NEW: User profiles for extended info
    mapping(address => UserProfile) public users;
    
    struct UserProfile {
        string companyName;
        string businessType;
        bool isRegistered;
    }

    // Per-user, per-product status (like working version)
    mapping(address => mapping(uint256 => string)) public statuses;

    // Environmental readings per product
    mapping(uint256 => EnvironmentalReading[]) private environmentalReadings;

    // --- EVENTS ---
    event ProductCreated(uint256 indexed id, string name, address indexed manufacturer);
    event ProductTransferred(uint256 indexed id, address indexed from, address indexed to, IStructs.ProductStatus status);
    event ProductStatusUpdated(uint256 indexed id, IStructs.ProductStatus oldStatus, IStructs.ProductStatus newStatus, address indexed updatedBy);
    event UserRegistered(address indexed user, string role);
    event ProductLifecycleStepRecorded(uint256 indexed id, uint8 stage, uint256 timestamp, address indexed actor, string note);
    event EnvironmentalDataRecorded(uint256 indexed productId, int256 temperature, uint256 humidity);

    // --- MODIFIERS ---
    modifier onlyManufacturer() {
        require(
            keccak256(bytes(roles[msg.sender])) == keccak256(bytes("Manufacturer")),
            "Only Manufacturer allowed"
        );
        _;
    }

    modifier onlyProductOwner(uint256 _productId) {
        require(
            msg.sender == products[_productId].currentOwner,
            "Not the product owner"
        );
        _;
    }

    // --- REGISTER USER ---
    function registerUser(string memory _role) public {
        require(
            bytes(roles[msg.sender]).length == 0,
            "Already registered!"
        );
        roles[msg.sender] = _role;
        users[msg.sender].isRegistered = true;
        emit UserRegistered(msg.sender, _role);
    }

    // Extended registration with company info
    function registerUserWithDetails(
        string memory _role,
        string memory _companyName,
        string memory _businessType
    ) public {
        require(
            bytes(roles[msg.sender]).length == 0,
            "Already registered!"
        );
        roles[msg.sender] = _role;
        users[msg.sender] = UserProfile({
            companyName: _companyName,
            businessType: _businessType,
            isRegistered: true
        });
        emit UserRegistered(msg.sender, _role);
    }

    // --- CREATE PRODUCT (SIMPLE VERSION - backward compatible) ---
    function createProduct(string memory _name, string memory _serial) public returns (uint256) {
        return createProductAdvanced(
            _name,
            _serial,
            "", // batchNumber
            IStructs.ProductCategory.DryGoods,
            1, // quantity
            0, // unitCost
            0, // expiryDate
            false, // requiresTemperatureControl
            0, // minTemperature
            0  // maxTemperature
        );
    }

    // --- CREATE PRODUCT (ADVANCED VERSION) ---
    function createProductAdvanced(
        string memory _name,
        string memory _serial,
        string memory _batch,
        IStructs.ProductCategory _category,
        uint256 _quantity,
        uint256 _unitCost,
        uint256 _expiryDate,
        bool _requiresTempControl,
        int256 _minTemp,
        int256 _maxTemp
    ) public onlyManufacturer returns (uint256) {
        productCount++;
        uint256 newId = productCount;

        Product storage p = products[newId];
        p.id = newId;
        p.name = _name;
        p.serialNumber = _serial;
        p.batchNumber = _batch;
        p.category = _category;
        p.status = IStructs.ProductStatus.Created;
        p.currentOwner = msg.sender;
        p.manufacturer = msg.sender;
        p.quantity = _quantity;
        p.unitCost = _unitCost;
        p.createdAt = block.timestamp;
        p.expiryDate = _expiryDate;
        p.requiresTemperatureControl = _requiresTempControl;
        p.minTemperature = _minTemp;
        p.maxTemperature = _maxTemp;
        p.history.push(msg.sender);
        p.historyTimestamps.push(block.timestamp);

        // Manufacturer's view: product is in their warehouse
        statuses[msg.sender][newId] = "In Warehouse";

        emit ProductCreated(newId, _name, msg.sender);
        emit ProductLifecycleStepRecorded(newId, uint8(IStructs.ProductStatus.Created), block.timestamp, msg.sender, "Product created");

        return newId;
    }

    // --- TRANSFER PRODUCT ---
    function transferProduct(uint256 _productId, address _newOwner) public onlyProductOwner(_productId) {
        require(_newOwner != address(0), "Invalid address");

        Product storage p = products[_productId];
        address previousOwner = p.currentOwner;

        p.currentOwner = _newOwner;
        p.history.push(_newOwner);
        p.historyTimestamps.push(block.timestamp);

        // Update status to InTransit
        IStructs.ProductStatus oldStatus = p.status;
        p.status = IStructs.ProductStatus.InTransit;

        // Sender's view: product has been transferred out
        statuses[msg.sender][_productId] = "Transferred";

        // Receiver's view: product is now in their warehouse
        statuses[_newOwner][_productId] = "In Warehouse";

        emit ProductTransferred(_productId, previousOwner, _newOwner, p.status);
        emit ProductStatusUpdated(_productId, oldStatus, p.status, msg.sender);
        emit ProductLifecycleStepRecorded(_productId, uint8(p.status), block.timestamp, msg.sender, "Product transferred");
    }

    // --- UPDATE PRODUCT STATUS ---
    function updateProductStatus(uint256 _productId, IStructs.ProductStatus _newStatus) public onlyProductOwner(_productId) {
        Product storage p = products[_productId];
        IStructs.ProductStatus oldStatus = p.status;
        p.status = _newStatus;

        emit ProductStatusUpdated(_productId, oldStatus, _newStatus, msg.sender);
        emit ProductLifecycleStepRecorded(_productId, uint8(_newStatus), block.timestamp, msg.sender, "Status updated");
    }

    // --- RECORD ENVIRONMENTAL DATA ---
    function recordEnvironmentalData(
        uint256 _productId,
        int256 _temperature,
        uint256 _humidity
    ) public {
        require(_productId > 0 && _productId <= productCount, "Invalid product ID");
        
        environmentalReadings[_productId].push(EnvironmentalReading({
            temperature: _temperature,
            humidity: _humidity,
            timestamp: block.timestamp,
            recordedBy: msg.sender
        }));

        emit EnvironmentalDataRecorded(_productId, _temperature, _humidity);

        // Check for temperature violations
        Product storage p = products[_productId];
        if (p.requiresTemperatureControl) {
            if (_temperature < p.minTemperature || _temperature > p.maxTemperature) {
                // Temperature violation - update status
                statuses[msg.sender][_productId] = "Temperature Alert";
            }
        }
    }

    // --- READ PRODUCT (SIMPLE - for backward compatibility) ---
    function getProduct(uint256 _productId)
        public
        view
        returns (
            uint256,
            string memory,
            string memory,
            address,
            string memory
        )
    {
        Product storage p = products[_productId];
        string memory myStatus = statuses[msg.sender][_productId];
        return (p.id, p.name, p.serialNumber, p.currentOwner, myStatus);
    }

    // --- READ PRODUCT (ADVANCED) ---
    function getProductDetails(uint256 _productId)
        public
        view
        returns (
            uint256 id,
            string memory name,
            string memory serialNumber,
            string memory batchNumber,
            IStructs.ProductCategory category,
            IStructs.ProductStatus status,
            address currentOwner,
            address manufacturer,
            uint256 quantity,
            uint256 unitCost,
            uint256 createdAt,
            uint256 expiryDate,
            bool requiresTemperatureControl,
            int256 minTemperature,
            int256 maxTemperature
        )
    {
        Product storage p = products[_productId];
        return (
            p.id,
            p.name,
            p.serialNumber,
            p.batchNumber,
            p.category,
            p.status,
            p.currentOwner,
            p.manufacturer,
            p.quantity,
            p.unitCost,
            p.createdAt,
            p.expiryDate,
            p.requiresTemperatureControl,
            p.minTemperature,
            p.maxTemperature
        );
    }

    // --- READ HISTORY ---
    function getProductHistory(uint256 _productId)
        public
        view
        returns (address[] memory, uint256[] memory)
    {
        Product storage p = products[_productId];
        return (p.history, p.historyTimestamps);
    }

    // --- GET ENVIRONMENTAL READINGS ---
    function getEnvironmentalReadings(uint256 _productId)
        public
        view
        returns (EnvironmentalReading[] memory)
    {
        return environmentalReadings[_productId];
    }

    // --- GET USER PROFILE ---
    function getUserProfile(address _user)
        public
        view
        returns (
            string memory role,
            string memory companyName,
            string memory businessType,
            bool isRegistered
        )
    {
        return (
            roles[_user],
            users[_user].companyName,
            users[_user].businessType,
            users[_user].isRegistered
        );
    }
}

