// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title SupplyChainSimple
 * @dev Enhanced supply chain with role-based access, lifecycle tracking, and financial integration
 */
contract SupplyChainSimple {
    
    struct Product {
        uint256 id;
        string name;
        string serialNumber;
        string batchNumber;
        address currentOwner;
        address manufacturer;
        uint256 quantity;
        uint256 unitCost;
        uint256 createdAt;
        address[] history;
        uint256[] historyTimestamps;
        bool requiresTemperatureControl;
        int256 minTemperature;
        int256 maxTemperature;
    }

    struct EnvironmentalReading {
        int256 temperature;
        uint256 humidity;
        uint256 timestamp;
        address recordedBy;
    }

    mapping(uint256 => Product) public products;
    uint256 public productCount = 0;

    // Role of each address: "Manufacturer", "Distributor", "Retailer", "Customer"
    mapping(address => string) public roles;

    // Per-user, per-product status
    mapping(address => mapping(uint256 => string)) public statuses;

    // Environmental readings per product
    mapping(uint256 => EnvironmentalReading[]) public environmentalReadings;

    // Events
    event ProductCreated(uint256 indexed id, string name, address indexed manufacturer);
    event ProductTransferred(uint256 indexed id, address indexed from, address indexed to);
    event UserRegistered(address indexed user, string role);
    event ProductLifecycleStepRecorded(uint256 indexed id, uint8 stage, uint256 timestamp, address indexed actor, string note);
    event EnvironmentalDataRecorded(uint256 indexed productId, int256 temperature, uint256 humidity);

    // --- REGISTER USER ---
    function registerUser(string memory _role) public {
        require(
            bytes(roles[msg.sender]).length == 0,
            "Error: You are already registered!"
        );
        roles[msg.sender] = _role;
        emit UserRegistered(msg.sender, _role);
    }

    // --- CREATE PRODUCT (MANUFACTURER) ---
    function createProduct(
        string memory _name,
        string memory _serial,
        string memory _batch,
        uint256 _quantity,
        uint256 _unitCost,
        bool _requiresTempControl,
        int256 _minTemp,
        int256 _maxTemp
    ) public returns (uint256) {
        require(
            keccak256(bytes(roles[msg.sender])) == keccak256(bytes("Manufacturer")),
            "Error: Only Manufacturer can create!"
        );

        productCount++;
        uint256 newId = productCount;

        Product storage newProduct = products[newId];
        newProduct.id = newId;
        newProduct.name = _name;
        newProduct.serialNumber = _serial;
        newProduct.batchNumber = _batch;
        newProduct.currentOwner = msg.sender;
        newProduct.manufacturer = msg.sender;
        newProduct.quantity = _quantity;
        newProduct.unitCost = _unitCost;
        newProduct.createdAt = block.timestamp;
        newProduct.requiresTemperatureControl = _requiresTempControl;
        newProduct.minTemperature = _minTemp;
        newProduct.maxTemperature = _maxTemp;
        newProduct.history.push(msg.sender);
        newProduct.historyTimestamps.push(block.timestamp);

        // Manufacturer's view: this product is currently in their warehouse
        statuses[msg.sender][newId] = "In Warehouse";

        emit ProductCreated(newId, _name, msg.sender);
        emit ProductLifecycleStepRecorded(newId, 0, block.timestamp, msg.sender, "Product created");

        return newId;
    }

    // --- SIMPLIFIED CREATE (for backward compatibility) ---
    function createProduct(string memory _name, string memory _serial) public returns (uint256) {
        return createProduct(_name, _serial, "", 1, 0, false, 0, 0);
    }

    // --- TRANSFER PRODUCT ---
    function transferProduct(uint256 _productId, address _newOwner) public {
        require(
            msg.sender == products[_productId].currentOwner,
            "Error: You are not the owner."
        );
        require(_newOwner != address(0), "Error: Invalid address.");

        // Update current owner
        products[_productId].currentOwner = _newOwner;
        products[_productId].history.push(_newOwner);
        products[_productId].historyTimestamps.push(block.timestamp);

        // Sender's view: product has been transferred out
        statuses[msg.sender][_productId] = "Transferred";

        // Receiver's view: product is now in their warehouse
        statuses[_newOwner][_productId] = "In Warehouse";

        emit ProductTransferred(_productId, msg.sender, _newOwner);
        emit ProductLifecycleStepRecorded(_productId, 1, block.timestamp, msg.sender, "Product transferred");
    }

    // --- RECORD ENVIRONMENTAL DATA ---
    function recordEnvironmentalData(
        uint256 _productId,
        int256 _temperature,
        uint256 _humidity
    ) public {
        require(_productId > 0 && _productId <= productCount, "Invalid product ID");
        
        environmentalReadings[_productId].push(EnvironmentalReading({
            temperature: _temperature,
            humidity: _humidity,
            timestamp: block.timestamp,
            recordedBy: msg.sender
        }));

        emit EnvironmentalDataRecorded(_productId, _temperature, _humidity);
    }

    // --- READ HISTORY ---
    function getProductHistory(uint256 _productId)
        public
        view
        returns (address[] memory, uint256[] memory)
    {
        Product storage p = products[_productId];
        return (p.history, p.historyTimestamps);
    }

    // --- READ PRODUCT + CALLER-SPECIFIC STATUS ---
    function getProduct(uint256 _productId)
        public
        view
        returns (
            uint256,
            string memory,
            string memory,
            address,
            string memory
        )
    {
        Product memory p = products[_productId];
        string memory myStatus = statuses[msg.sender][_productId];
        return (p.id, p.name, p.serialNumber, p.currentOwner, myStatus);
    }

    // --- GET FULL PRODUCT DETAILS ---
    function getProductDetails(uint256 _productId)
        public
        view
        returns (
            uint256 id,
            string memory name,
            string memory serialNumber,
            string memory batchNumber,
            address currentOwner,
            address manufacturer,
            uint256 quantity,
            uint256 unitCost,
            uint256 createdAt,
            bool requiresTemperatureControl,
            int256 minTemperature,
            int256 maxTemperature
        )
    {
        Product storage p = products[_productId];
        return (
            p.id,
            p.name,
            p.serialNumber,
            p.batchNumber,
            p.currentOwner,
            p.manufacturer,
            p.quantity,
            p.unitCost,
            p.createdAt,
            p.requiresTemperatureControl,
            p.minTemperature,
            p.maxTemperature
        );
    }

    // --- GET ENVIRONMENTAL READINGS ---
    function getEnvironmentalReadings(uint256 _productId)
        public
        view
        returns (EnvironmentalReading[] memory)
    {
        return environmentalReadings[_productId];
    }
}
